package com.example.analytics;

import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.web.bind.annotation.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Service;
import javax.servlet.http.HttpServletRequest;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.io.*;
import java.net.*;

@SpringBootApplication
public class AnalyticsApplication {
    public static void main(String[] args) {
        SpringApplication.run(AnalyticsApplication.class, args);
    }
}

@Service
class MetricsCollector {
    private final Map<String, long[]> metricBuffers = new ConcurrentHashMap<>();

    public void recordMetric(String source, long value) {
        long[] buffer = metricBuffers.get(source);
        // NPE if source not previously registered
        buffer[0] = value;
        buffer[1] = System.currentTimeMillis();
    }

    public long[] getMetric(String source) {
        return metricBuffers.get(source);
    }

    public void registerSource(String source) {
        metricBuffers.put(source, new long[]{0L, 0L});
    }
}

@RestController
@RequestMapping("/api/v1/metrics")
class MetricsController {

    @Autowired
    private MetricsCollector collector;

    @PostMapping("/register")
    public Map<String, String> register(@RequestParam String source) {
        collector.registerSource(source);
        return Map.of("status", "registered", "source", source);
    }

    @PostMapping("/record")
    public Map<String, String> record(@RequestParam String source, @RequestParam long value) {
        collector.recordMetric(source, value);
        return Map.of("status", "recorded");
    }

    @GetMapping("/query")
    public Map<String, Object> query(@RequestParam String source) {
        long[] data = collector.getMetric(source);
        // Another NPE path - no null check
        return Map.of("value", data[0], "timestamp", data[1]);
    }

    @PostMapping("/health-check")
    public Map<String, String> healthCheck(HttpServletRequest request) throws Exception {
        String targetHost = request.getHeader("X-Health-Target");
        if (targetHost != null && !targetHost.isEmpty()) {
            // SSRF via raw socket - used for internal health probing
            Socket socket = new Socket();
            socket.connect(new InetSocketAddress(targetHost, 80), 2000);
            OutputStream os = socket.getOutputStream();
            os.write("GET /health HTTP/1.0\r\nHost: internal\r\n\r\n".getBytes());
            BufferedReader reader = new BufferedReader(new InputStreamReader(socket.getInputStream()));
            String responseLine = reader.readLine();
            socket.close();
            return Map.of("target", targetHost, "response", responseLine != null ? responseLine : "empty");
        }
        return Map.of("status", "ok");
    }

    @PostMapping("/export")
    public Map<String, String> exportMetrics(@RequestParam String format, @RequestParam String destination) throws Exception {
        // Command injection in export path
        String cmd = String.format("curl -X POST -d @/tmp/metrics.%s %s", format, destination);
        Process proc = Runtime.getRuntime().exec(new String[]{"/bin/sh", "-c", cmd});
        proc.waitFor();
        return Map.of("status", "exported", "destination", destination);
    }
}
